---
title: "Remote Agent Browser"
navTitle: "Remote Agent Browser"
---

[Remote Agent Browser](https://github.com/vercel-labs/remote-agent-browser) runs agent-browser inside an isolated [Vercel Sandbox](https://vercel.com/docs/vercel-sandbox). Use it when a TypeScript application needs to provision a browser on demand without managing a local Chrome process.

Remote Agent Browser is a library rather than an agent-browser `-p` provider. Import it in your application and use the returned client to run agent-browser commands.

## Setup

```bash
pnpm add remote-agent-browser
```

Authentication is automatic on Vercel through `VERCEL_OIDC_TOKEN`. For local development, link a Vercel project and pull its environment:

```bash
vercel link
vercel env pull .env.local
```

## Create a browser

```ts
import { AgentBrowser } from "remote-agent-browser";

const browser = await AgentBrowser.create();

try {
  await browser.exec("open", {
    args: ["https://example.com"],
  });

  const snapshot = await browser.exec("snapshot");
  console.log(snapshot.stdout);
} finally {
  await browser.close();
}
```

Commands issued through the same client share the same page, cookies, tabs, and element references. Always close disposable clients when the work is complete.

## Stable browser sessions

Use a stable ID when browser identity needs to survive process boundaries:

```ts
const browser = AgentBrowser.session({
  id: `chat:${chatId}`,
});

const stopKeepalive = browser.keepalive();

try {
  await browser.exec("open", {
    args: ["https://example.com"],
  });
} finally {
  stopKeepalive();
}
```

The first command finds or creates the named Sandbox. A later process using the same ID can attach to it. If an expired Sandbox resumes, Chromium starts fresh and in-memory page state is reset.

## Custom browser image

The default image is `remote-agent-browser:latest`. Pass a Vercel Container Registry repository, tag, digest, or fully qualified reference to use a custom image:

```ts
const browser = await AgentBrowser.create({
  image: "vcr.vercel.com/my-team/my-project/my-browser:v1",
});
```

You can also set `REMOTE_AGENT_BROWSER_IMAGE` to configure the image for every client.

## Options

<table>
  <thead>
    <tr><th>Option</th><th>Description</th><th>Default</th></tr>
  </thead>
  <tbody>
    <tr><td><code>image</code></td><td>Vercel Container Registry image containing agent-browser and Chromium</td><td><code>remote-agent-browser:latest</code></td></tr>
    <tr><td><code>timeoutMs</code></td><td>Sandbox wall-clock timeout in milliseconds</td><td><code>600000</code></td></tr>
    <tr><td><code>vcpus</code></td><td>Number of Sandbox vCPUs</td><td><code>2</code></td></tr>
    <tr><td><code>env</code></td><td>Additional environment variables for commands in the Sandbox</td><td><code>{}</code></td></tr>
    <tr><td><code>args</code></td><td>Global agent-browser CLI arguments applied to each command</td><td><code>[]</code></td></tr>
    <tr><td><code>proxy</code></td><td>Proxy URL or proxy configuration for the browser client</td><td>(none)</td></tr>
  </tbody>
</table>

See the [Remote Agent Browser repository](https://github.com/vercel-labs/remote-agent-browser) for file transfer, proxy configuration, typed JSON output, keepalive, and stable-session examples.

import assert from "node:assert/strict";
import test from "node:test";

import {
  CHROMIUM_SYSTEM_DEPS,
  createAgentBrowserSandbox,
  createAgentBrowserSnapshot,
  getSandboxCredentials,
  installAgentBrowserInVercelSandbox,
  runAgentBrowserCommand,
  withAgentBrowserSandbox,
} from "../dist/vercel.js";

test("default Vercel dependencies include certutil", () => {
  assert.ok(CHROMIUM_SYSTEM_DEPS.includes("nss-tools"));
});

function commandResult(stdout = "{}", stderr = "", exitCode = 0) {
  return {
    exitCode,
    async stderr() {
      return stderr;
    },
    async stdout() {
      return stdout;
    },
  };
}

test("imports vercel entry without loading a real @vercel/sandbox module", async () => {
  assert.equal(typeof getSandboxCredentials, "function");
});

test("reads explicit Vercel credentials", () => {
  assert.deepEqual(
    getSandboxCredentials({
      VERCEL_PROJECT_ID: "project",
      VERCEL_TEAM_ID: "team",
      VERCEL_TOKEN: "token",
    }),
    { projectId: "project", teamId: "team", token: "token" },
  );
  assert.deepEqual(getSandboxCredentials({}), {});
});

test("runs agent-browser command in a Vercel sandbox", async () => {
  const calls = [];
  const sandbox = {
    async runCommand(command, args) {
      calls.push([command, args]);
      return commandResult('{"ok":true}');
    },
  };

  const result = await runAgentBrowserCommand(sandbox, ["open", "https://example.com"], {
    session: "s1",
  });

  assert.deepEqual(result.json, { ok: true });
  assert.deepEqual(calls, [
    ["agent-browser", ["--session", "s1", "open", "https://example.com", "--json"]],
  ]);
});

test("creates and bootstraps a fresh Vercel sandbox", async () => {
  const calls = [];
  const sandbox = {
    async runCommand(command, args) {
      calls.push([command, args]);
      return commandResult();
    },
    async snapshot() {
      return { snapshotId: "snap" };
    },
    async stop() {},
  };
  const Sandbox = {
    async create(options) {
      calls.push(["create", options]);
      return sandbox;
    },
  };

  await createAgentBrowserSandbox({
    Sandbox,
    env: {},
    install: { installSpec: "agent-browser@1.2.3", systemDependencies: ["nss"] },
  });

  assert.equal(calls[0][0], "create");
  assert.deepEqual(calls[1], [
    "sh",
    [
      "-c",
      "sudo dnf clean all 2>&1 && sudo dnf install -y --skip-broken -- nss 2>&1 && sudo ldconfig 2>&1",
    ],
  ]);
  assert.deepEqual(calls[2], ["npm", ["install", "-g", "agent-browser@1.2.3"]]);
  assert.deepEqual(calls[3], ["agent-browser", ["install"]]);
});

test("skips Vercel system dependencies when explicitly disabled", async () => {
  const calls = [];
  const sandbox = {
    async runCommand(command, args) {
      calls.push([command, args]);
      return commandResult();
    },
  };

  await installAgentBrowserInVercelSandbox(sandbox, {
    installSpec: "agent-browser@1.2.3",
    installSystemDependencies: false,
  });

  assert.deepEqual(calls, [
    ["npm", ["install", "-g", "agent-browser@1.2.3"]],
    ["agent-browser", ["install"]],
  ]);
});

test("rejects invalid Vercel system dependency names", async () => {
  const calls = [];
  const sandbox = {
    async runCommand(command, args) {
      calls.push([command, args]);
      return commandResult();
    },
  };

  await assert.rejects(
    () =>
      installAgentBrowserInVercelSandbox(sandbox, {
        systemDependencies: ["nss; touch /tmp/pwned"],
      }),
    /Invalid system dependency name/,
  );
  assert.deepEqual(calls, []);
});

test("stops a fresh Vercel sandbox when bootstrap fails", async () => {
  let stopped = false;
  const sandbox = {
    async runCommand() {
      return commandResult("", "install failed", 1);
    },
    async snapshot() {
      return { snapshotId: "snap" };
    },
    async stop() {
      stopped = true;
    },
  };

  await assert.rejects(
    () =>
      createAgentBrowserSandbox({
        Sandbox: { async create() { return sandbox; } },
        env: {},
        install: { systemDependencies: [] },
      }),
    /install failed/,
  );
  assert.equal(stopped, true);
});

test("withAgentBrowserSandbox stops the sandbox", async () => {
  let stopped = false;
  const sandbox = {
    async runCommand() {
      return commandResult();
    },
    async snapshot() {
      return { snapshotId: "snap" };
    },
    async stop() {
      stopped = true;
    },
  };

  const value = await withAgentBrowserSandbox(async () => 42, {
    Sandbox: { async create() { return sandbox; } },
    bootstrap: false,
    env: {},
  });

  assert.equal(value, 42);
  assert.equal(stopped, true);
});

test("withAgentBrowserSandbox preserves callback failure when stop fails", async () => {
  const sandbox = {
    async runCommand() {
      return commandResult();
    },
    async snapshot() {
      return { snapshotId: "snap" };
    },
    async stop() {
      throw new Error("stop failed");
    },
  };

  await assert.rejects(
    () =>
      withAgentBrowserSandbox(
        async () => {
          throw new Error("work failed");
        },
        {
          Sandbox: { async create() { return sandbox; } },
          bootstrap: false,
          env: {},
        },
      ),
    /work failed/,
  );
});

test("withAgentBrowserSandbox surfaces stop failure after success", async () => {
  const sandbox = {
    async runCommand() {
      return commandResult();
    },
    async snapshot() {
      return { snapshotId: "snap" };
    },
    async stop() {
      throw new Error("stop failed");
    },
  };

  await assert.rejects(
    () =>
      withAgentBrowserSandbox(async () => 42, {
        Sandbox: { async create() { return sandbox; } },
        bootstrap: false,
        env: {},
      }),
    /stop failed/,
  );
});

test("creates a Vercel sandbox snapshot", async () => {
  const sandbox = {
    async runCommand() {
      return commandResult();
    },
    async snapshot() {
      return { snapshotId: "snap_123" };
    },
    async stop() {},
  };

  const snapshotId = await createAgentBrowserSnapshot({
    Sandbox: { async create() { return sandbox; } },
    env: {},
    install: { systemDependencies: [] },
  });

  assert.equal(snapshotId, "snap_123");
});

test("createAgentBrowserSnapshot preserves snapshot failure when stop fails", async () => {
  const sandbox = {
    async runCommand() {
      return commandResult();
    },
    async snapshot() {
      throw new Error("snapshot failed");
    },
    async stop() {
      throw new Error("stop failed");
    },
  };

  await assert.rejects(
    () =>
      createAgentBrowserSnapshot({
        Sandbox: { async create() { return sandbox; } },
        env: {},
        install: { systemDependencies: [] },
      }),
    /snapshot failed/,
  );
});

