/**
 * Run agent-browser inside a Vercel Sandbox.
 *
 * No external server needed -- a Linux microVM spins up on demand,
 * runs agent-browser + headless Chrome, and shuts down when done.
 *
 * For production, create a snapshot with agent-browser and Chromium
 * pre-installed so startup is sub-second instead of ~30s.
 */

import { Sandbox } from "@vercel/sandbox";

export type SandboxResult = {
  exitCode: number;
  stdout: string;
  stderr: string;
};

export type StepEvent = {
  step: string;
  status: "running" | "done" | "error";
  elapsed?: number;
};

export type OnStep = (event: StepEvent) => void;

const SNAPSHOT_ID = process.env.AGENT_BROWSER_SNAPSHOT_ID;

const CHROMIUM_SYSTEM_DEPS = [
  "nss",
  "nss-tools",
  "nspr",
  "libxkbcommon",
  "atk",
  "at-spi2-atk",
  "at-spi2-core",
  "libXcomposite",
  "libXdamage",
  "libXrandr",
  "libXfixes",
  "libXcursor",
  "libXi",
  "libXtst",
  "libXScrnSaver",
  "libXext",
  "mesa-libgbm",
  "libdrm",
  "mesa-libGL",
  "mesa-libEGL",
  "cups-libs",
  "alsa-lib",
  "pango",
  "cairo",
  "gtk3",
  "dbus-libs",
];

/**
 * Returns credentials to spread into Sandbox.create() calls.
 * When explicit env vars are set they take precedence; otherwise returns
 * an empty object so the SDK falls back to VERCEL_OIDC_TOKEN automatically.
 */
export function getSandboxCredentials():
  | { token: string; teamId: string; projectId: string }
  | Record<string, never> {
  if (
    process.env.VERCEL_TOKEN &&
    process.env.VERCEL_TEAM_ID &&
    process.env.VERCEL_PROJECT_ID
  ) {
    return {
      token: [REDACTED],
      teamId: process.env.VERCEL_TEAM_ID,
      projectId: process.env.VERCEL_PROJECT_ID,
    };
  }
  return {};
}

async function runStep<T>(
  step: string,
  fn: () => Promise<T>,
  onStep?: OnStep,
): Promise<T> {
  const start = Date.now();
  onStep?.({ step, status: "running" });
  try {
    const result = await fn();
    onStep?.({ step, status: "done", elapsed: Date.now() - start });
    return result;
  } catch (err) {
    onStep?.({ step, status: "error", elapsed: Date.now() - start });
    throw err;
  }
}

/**
 * Install system dependencies + agent-browser + Chromium into a fresh sandbox.
 * The sandbox base image is Amazon Linux (dnf).
 */
async function bootstrapSandbox(
  sandbox: InstanceType<typeof Sandbox>,
  onStep?: OnStep,
): Promise<void> {
  await runStep("Installing system dependencies", async () => {
    await sandbox.runCommand("sh", [
      "-c",
      `sudo dnf clean all 2>&1 && sudo dnf install -y --skip-broken ${CHROMIUM_SYSTEM_DEPS.join(" ")} 2>&1 && sudo ldconfig 2>&1`,
    ]);
  }, onStep);

  await runStep("Installing agent-browser", async () => {
    await sandbox.runCommand("npm", ["install", "-g", "agent-browser"]);
    await sandbox.runCommand("npx", ["agent-browser", "install"]);
  }, onStep);
}

async function createSandbox(
  onStep?: OnStep,
): Promise<InstanceType<typeof Sandbox>> {
  const credentials = getSandboxCredentials();

  return runStep(
    SNAPSHOT_ID ? "Booting sandbox from snapshot" : "Creating sandbox",
    async () => {
      if (SNAPSHOT_ID) {
        return Sandbox.create({
          ...credentials,
          source: { type: "snapshot", snapshotId: SNAPSHOT_ID },
          timeout: 120_000,
        });
      }

      const sb = await Sandbox.create({
        ...credentials,
        runtime: "node24",
        timeout: 120_000,
      });
      await bootstrapSandbox(sb, onStep);
      return sb;
    },
    onStep,
  );
}

async function exec(
  sandbox: InstanceType<typeof Sandbox>,
  cmd: string,
  args: string[],
  onStep?: OnStep,
  stepLabel?: string,
): Promise<SandboxResult> {
  const label = stepLabel || `${cmd} ${args.join(" ")}`;

  return runStep(label, async () => {
    const result = await sandbox.runCommand(cmd, args);
    const stdout = await result.stdout();
    const stderr = await result.stderr();

    if (result.exitCode !== 0) {
      throw new Error(
        `Command "${cmd} ${args.join(" ")}" failed (exit ${result.exitCode}): ${stderr || stdout}`,
      );
    }

    return { exitCode: result.exitCode, stdout, stderr };
  }, onStep);
}

/**
 * Screenshot a URL using agent-browser inside a Vercel Sandbox.
 * Returns base64-encoded PNG.
 */
export async function screenshotUrl(
  url: string,
  opts: { fullPage?: boolean; onStep?: OnStep } = {},
): Promise<{ screenshot: string; title: string }> {
  const { onStep } = opts;
  const sandbox = await createSandbox(onStep);

  try {
    await exec(sandbox, "agent-browser", ["open", "about:blank"], onStep, "Starting browser");
    await exec(sandbox, "agent-browser", ["open", url], onStep, `Navigating to ${url}`);

    const titleResult = await exec(
      sandbox,
      "agent-browser",
      ["get", "title", "--json"],
      onStep,
      "Getting page title",
    );
    const title = tryParseJson(titleResult.stdout)?.data?.title || url;

    const screenshotArgs = ["screenshot", "--json"];
    if (opts.fullPage) screenshotArgs.push("--full");
    const ssResult = await exec(
      sandbox,
      "agent-browser",
      screenshotArgs,
      onStep,
      "Taking screenshot",
    );
    const ssData = tryParseJson(ssResult.stdout)?.data;
    const screenshotPath = ssData?.path;

    if (!screenshotPath) {
      throw new Error(
        `Screenshot returned no file path. Raw output: ${ssResult.stdout.slice(0, 500)}`,
      );
    }

    const b64Result = await exec(
      sandbox,
      "base64",
      ["-w", "0", screenshotPath],
      onStep,
      "Encoding screenshot",
    );
    const screenshot = b64Result.stdout.trim();

    if (!screenshot) {
      throw new Error("Failed to read screenshot file from sandbox");
    }

    await exec(sandbox, "agent-browser", ["close"], onStep, "Closing browser");

    return { screenshot, title };
  } finally {
    await runStep("Stopping sandbox", () => sandbox.stop(), onStep);
  }
}

/**
 * Snapshot a URL (accessibility tree) using agent-browser inside a Vercel Sandbox.
 */
export async function snapshotUrl(
  url: string,
  opts: { interactive?: boolean; compact?: boolean; onStep?: OnStep } = {},
): Promise<{ snapshot: string; title: string }> {
  const { onStep } = opts;
  const sandbox = await createSandbox(onStep);

  try {
    await exec(sandbox, "agent-browser", ["open", "about:blank"], onStep, "Starting browser");
    await exec(sandbox, "agent-browser", ["open", url], onStep, `Navigating to ${url}`);

    const titleResult = await exec(
      sandbox,
      "agent-browser",
      ["get", "title", "--json"],
      onStep,
      "Getting page title",
    );
    const title = tryParseJson(titleResult.stdout)?.data?.title || url;

    const snapshotArgs = ["snapshot"];
    if (opts.interactive) snapshotArgs.push("-i");
    if (opts.compact) snapshotArgs.push("-c");
    const snapResult = await exec(
      sandbox,
      "agent-browser",
      snapshotArgs,
      onStep,
      "Taking accessibility snapshot",
    );

    if (!snapResult.stdout.trim()) {
      throw new Error("Snapshot returned empty data");
    }

    await exec(sandbox, "agent-browser", ["close"], onStep, "Closing browser");

    return { snapshot: snapResult.stdout, title };
  } finally {
    await runStep("Stopping sandbox", () => sandbox.stop(), onStep);
  }
}

/**
 * Run arbitrary agent-browser commands inside a Vercel Sandbox.
 * Each command is a string array like ["open", "https://example.com"].
 */
export async function runCommands(
  commands: string[][],
): Promise<SandboxResult[]> {
  const sandbox = await createSandbox();

  try {
    const results: SandboxResult[] = [];
    for (const args of commands) {
      const result = await exec(sandbox, "agent-browser", args);
      results.push(result);
    }
    return results;
  } finally {
    await sandbox.stop();
  }
}

/**
 * Create a reusable snapshot with agent-browser + Chromium pre-installed.
 * Run this once, then set AGENT_BROWSER_SNAPSHOT_ID for fast startup.
 */
export async function createSnapshot(): Promise<string> {
  const sandbox = await Sandbox.create({
    ...getSandboxCredentials(),
    runtime: "node24",
    timeout: 300_000,
  });

  await bootstrapSandbox(sandbox);

  const snapshot = await sandbox.snapshot();
  return snapshot.snapshotId;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function tryParseJson(str: string): any {
  try {
    return JSON.parse(str);
  } catch {
    return null;
  }
}

import { agentBrowserRevalidationKey, installAgentBrowser } from "@agent-browser/eve/sandbox";
import { defineSandbox } from "eve/sandbox";
import { vercel } from "eve/sandbox/vercel";

export default defineSandbox({
  backend: vercel({ resources: { vcpus: 2 } }),
  revalidationKey: () => agentBrowserRevalidationKey(),
  async bootstrap({ use }) {
    const sandbox = await use();
    await installAgentBrowser(sandbox);
  },
});

# @agent-browser/eve

An [eve](https://eve.dev) extension that gives your agent a full browser automation tool set, backed by [agent-browser](https://agent-browser.dev) running inside the agent's sandbox.

Mount it once and the agent gets ~20 namespaced tools — navigation, accessibility snapshots with stable element refs, clicking, form filling, semantic element finding, waiting, screenshots, JavaScript evaluation, tab management, network and console inspection — without writing a single tool by hand.

## Install

```bash
npm install @agent-browser/eve
```

`eve` is a peer dependency; the extension runs on the eve installed in your app.

## Mount

Create a mount file under `agent/extensions/`. The file name becomes the tool namespace:

```ts
// agent/extensions/browser.ts
import browser from "@agent-browser/eve";

export default browser({});
```

That's it. The agent now has `browser__navigate`, `browser__snapshot`, `browser__click`, and the rest, plus an instructions fragment teaching the model the snapshot-refs workflow.

On first tool use in a fresh sandbox, the extension installs agent-browser (and Chromium plus its system libraries) automatically. For production, pre-install in your sandbox bootstrap instead so sessions start from a warm template:

```ts
// agent/sandbox.ts
import { agentBrowserRevalidationKey, installAgentBrowser } from "@agent-browser/eve/sandbox";
import { defineSandbox } from "eve/sandbox";
import { vercel } from "eve/sandbox/vercel";

export default defineSandbox({
  backend: vercel({ resources: { vcpus: 2 } }),
  revalidationKey: () => agentBrowserRevalidationKey(),
  async bootstrap({ use }) {
    const sandbox = await use();
    await installAgentBrowser(sandbox);
  },
});
```

`@agent-browser/eve/sandbox` also exports `runAgentBrowser` for calling agent-browser from a hand-written eve tool. It uses one default browser session per sandbox; pass `session` when multiple independent browser sessions should share one sandbox.

## Configuration

All fields are optional:

```ts
export default browser({
  // Safety
  allowedDomains: ["example.com", "*.example.com"], // restrict navigation and sub-resources
  caCert: "/etc/ssl/certs/proxy-ca.pem",
  clearCaCert: false,
  useSystemCa: true, // OS trust store for the CLI's own HTTPS requests, such as read
  contentBoundaries: true, // wrap page output in markers the model can recognize
  maxOutputChars: 50_000, // truncate page output

  // Output
  inlineScreenshots: true, // embed screenshots in tool output as data URLs for channels/UIs
  // (hidden from the model via toModelOutput; capped at 4 MB per image)

  // Install behavior
  autoInstall: true, // install agent-browser on first use when missing
  installSpec: "agent-browser@0.31.2", // defaults to the version matching this package
  installBrowser: true, // download Chromium during auto-install
  installSystemDependencies: true, // apt/dnf Chromium libraries during auto-install

  // Session & runtime
  session: undefined, // fixed session name; defaults to one derived from the sandbox id
  sessionPrefix: "eve", // prefix for the derived session name
  binary: "agent-browser", // binary name or path inside the sandbox
  proxy: undefined, // proxy server URL
});
```

## Tools

| Tool | Purpose |
| --- | --- |
| `navigate` | Open a URL, or go back/forward/reload |
| `snapshot` | Accessibility tree with `@eN` element refs (the primary way to see a page) |
| `read` | Page as agent-friendly text/markdown, `llms.txt` aware |
| `click` | Click or double-click an element |
| `fill` | Type into an input (clearing first by default) |
| `press_key` | Press a key or combination (`Enter`, `Control+a`) |
| `hover` | Hover an element |
| `select_option` | Pick a `<select>` option |
| `set_checked` | Check/uncheck a checkbox or radio |
| `scroll` | Scroll the page, a container, or an element into view |
| `drag` | Drag and drop |
| `upload` | Attach sandbox files to a file input |
| `wait_for` | Wait for an element, text, URL pattern, load state, JS condition, or delay |
| `get` | Read text/html/value/attribute/title/url/count/box/styles |
| `find` | Semantic locator: act on an element by role, label, text, placeholder, or test id |
| `screenshot` | Capture the page (full-page and annotated modes); output includes an inline data URL for UIs |
| `evaluate` | Run JavaScript in the page |
| `tabs` | List/open/switch/close tabs (stable ids and labels) |
| `console` | Read console messages and uncaught page errors |
| `network_requests` | List tracked requests or fetch one request's full detail |
| `close` | Close the browser session |

Cookie, storage, and saved-auth-state commands are intentionally not exposed as tools — they make credential material visible to the model. If you need them, add a scoped tool in your own agent (or an [override](#overrides)) with the guardrails your app requires.

## Overrides

Standard eve extension overrides apply. Mount as a directory to gate or replace individual tools:

```ts
// agent/extensions/browser/extension.ts
import browser from "@agent-browser/eve";

export default browser({});
```

```ts
// agent/extensions/browser/tools/evaluate.ts — require approval for raw JS
import { evaluate } from "@agent-browser/eve/tools";
import { defineTool } from "eve/tools";
import { always } from "eve/tools/approval";

export default defineTool({ ...evaluate, approval: always() });
```

```ts
// agent/extensions/browser/tools/upload.ts — or drop a tool entirely
import { disableTool } from "eve/tools";

export default disableTool();
```

## How it works

Each tool shells out to the `agent-browser` CLI inside the sandbox from `ctx.getSandbox()`, using an isolated browser session named after the sandbox id, and returns the parsed `--json` payload. The browser and its state live entirely in the sandbox; the app runtime only relays commands.

## Example

See [`examples/eve`](https://github.com/vercel-labs/agent-browser/tree/main/examples/eve) for a complete Next.js eve app with this extension mounted.

