    throw new Error(
      "Production docs server did not become ready within 60 seconds",
    );
  if (!stopping) {
    console.log(
      `Testing owned production server ${env.DOCS_TEST_URL}; VERCEL_ENV=${env.VERCEL_ENV}`,
    );
    const asset = await fetch(`${env.DOCS_TEST_URL}/api/mcp?webmcp-script`);
